style.css:
/* Hide YouTube’s default logo */
ytd-topbar-logo-renderer svg {
  display: none !important;
}

/* Apply the Knuckles GIF as the YouTube logo */
ytd-topbar-logo-renderer {
  width: 56px !important;
  height: 56px !important;

  background-image: url("https://media.tenor.com/rBXbhw-NgTIAAAAi/knuckles-the-echidna.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;

  image-rendering: pixelated;
}

/* Optional hover punch/bounce */
ytd-topbar-logo-renderer:hover {
  animation: knucklesBounce 0.4s infinite alternate;
}

@keyframes knucklesBounce {
  from { transform: translateY(0); }
  to   { transform: translateY(-4px); }
}
